  const parts = String(s || '').split('/Users/');
  if (parts.length === 1) return parts[0];
  let out = parts[0];
  for (let i = 1; i < parts.length; i += 1) out += parts[i].split(' ').slice(1).join(' ');
  return out;
}
function compact(s) {
  return String(s || '').split(String.fromCharCode(10)).join(' ').split(String.fromCharCode(9)).join(' ').split(' ').filter(Boolean).join(' ').trim();
}
